no-case-declarations:
export function pick(x: number): number {
  switch (x) {
    case 1:
      const y = 1;
      return y;
    default:
      return 0;
  }
}

no-prototype-builtins:
export function has(o: object): boolean {
  return o.hasOwnProperty('a');
}

no-compare-neg-zero:
export function zero(x: number): boolean {
  return x == -0;
}

@typescript-eslint/no-unnecessary-type-c:
export function keep<T extends any>(a: T): T {
  return a;
}

@typescript-eslint/no-non-null-asserted-:
declare function read(): string | undefined;

export function pick(): string {
  const a = read();
  return a! ?? 'x';
}

export function name(a?: { b: string }): string {
  return a?.b!;
}

use-isnan:
export function bad(x: number): boolean {
  return x === NaN;
}

preserve-caught-error:
export function wrap(): number {
  try {
    return 1;
  } catch (error) {
    throw new Error('failed');
  }
}

@typescript-eslint/require-await:
export async function one(): Promise<number> {
  return 1;
}

@typescript-eslint/await-thenable:
export async function wait(a: number): Promise<number> {
  return await a;
}

@typescript-eslint/ban-ts-comment:
export function cast(): string {
  // @ts-ignore
  return 1 as string;
}

@typescript-eslint/no-array-delete:
export function drop(items: number[]): void {
  delete items[0];
}

@typescript-eslint/use-unknown-in-catch-:
export function recover(p: Promise<number>): Promise<number> {
  return p.catch((e) => 0);
}

@typescript-eslint/switch-exhaustiveness:
type Mode = 'a' | 'b';

export function label(m: Mode): number {
  switch (m) {
    case 'a':
      return 1;
  }
  return 0;
}

two-suggestions:
export function same(x: number): boolean {
  return x === -0;
}
